/**
 * Detox runs against the iOS simulator only, in Debug, which is the build that loads its JS from
 * Metro — `scripts/e2e-test.sh` is what makes sure Metro is there.
 *
 * `iPhone 16-Detox` is matched by name rather than created: the device already exists on the
 * machine this was built on, and Detox will reuse a named simulator but happily make a second one
 * under a different name.
 *
 * The binary path is where `-derivedDataPath ios/build` puts it, so nothing has to be guessed out
 * of Xcode's shared DerivedData. `ios/` is generated by `pnpm e2e:build` and git-ignored.
 *
 * **If a spec fails on a missing JS export, run `pnpm e2e:build` before you debug the spec.**
 * This binary has native code compiled into it, so adding or changing a native module means
 * rebuilding it — a JS reload is not enough, and the simulator reports the module's JS half as
 * undefined rather than reporting a build problem. Every native module the app plans to have
 * (async-storage, Reanimated, Worklets, Screens, Safe Area Context) was already installed when
 * this was first built, which is why the build is normally run once and left alone.
 */
module.exports = {
  testRunner: {
    args: { $0: 'jest', config: 'e2e/jest.config.js' },
    jest: { setupTimeout: 180_000 },
  },
  apps: {
    'ios.debug': {
      type: 'ios.app',
      binaryPath: 'ios/build/Build/Products/Debug-iphonesimulator/Repairs.app',
      build:
        'xcodebuild -workspace ios/Repairs.xcworkspace -scheme Repairs -configuration Debug -sdk iphonesimulator -derivedDataPath ios/build -quiet',
    },
  },
  devices: {
    simulator: {
      type: 'ios.simulator',
      device: { name: 'iPhone 16-Detox' },
      // Xcode 27 no longer ships a launchable `Simulator.app`, so Detox's attempt to open the
      // simulator window fails, retries for ~25s and prints "Unable to find application named
      // 'Simulator'" before carrying on regardless. The device boots either way; this skips the
      // detour. Drop it if a future Xcode brings the app back and you want to watch the run.
      headless: true,
    },
  },
  configurations: {
    'ios.sim.debug': { device: 'simulator', app: 'ios.debug' },
  },
};
